// Helper functions
func truncateCommit(commit string) string {
	if len(commit) > 8 {
		return commit[:8]
	}
	return commit
}

func getServiceStatusBadge(status string) string {
	switch status {
	case "active":
		return "badge-success"
	case "inactive":
		return "badge-muted"
	case "failed":
		return "badge-danger"
	default:
		return "badge-warning"
	}
}

func getProcessStatusBadge(status string) string {
	switch status {
	case "running", "R":
		return "badge-success"
	case "sleeping", "S":
		return "badge-info"
	case "stopped", "T":
		return "badge-warning"
	case "zombie", "Z":
		return "badge-danger"
	default:
		return "badge-muted"
	}
}

